#include <bits/stdc++.h>
#include <boost/multiprecision/cpp_int.hpp>
using namespace std; using boost::multiprecision::cpp_int; using U=unsigned __int128;
static int K=14,B=80; static vector<uint32_t>codes; static unordered_map<uint32_t,uint32_t>idx;
static void gen(int dep,int x,int y,uint32_t code,vector<pair<int,int>>&p){if(dep==K){codes.push_back(code);return;}static int dx[4]={1,-1,0,0},dy[4]={0,0,1,-1};for(int d=0;d<4;d++){int nx=x+dx[d],ny=y+dy[d];bool ok=1;for(auto z:p)if(z.first==nx&&z.second==ny){ok=0;break;}if(ok){p.push_back({nx,ny});gen(dep+1,nx,ny,(code<<2)|d,p);p.pop_back();}}}
static bool okapp(uint32_t code,int d){static int dx[4]={1,-1,0,0},dy[4]={0,0,1,-1};int x=0,y=0;pair<int,int> p[18];int n=1;p[0]={0,0};for(int i=K-1;i>=0;--i){int q=(code>>(2*i))&3;x+=dx[q];y+=dy[q];p[n++]={x,y};}x+=dx[d];y+=dy[d];for(int i=0;i<n;i++)if(p[i].first==x&&p[i].second==y)return 0;return 1;}
static cpp_int tobig(U x){cpp_int z=(uint64_t)(x>>64);z<<=64;z+=(uint64_t)x;return z;}
int main(int ac,char**av){if(ac>1)K=atoi(av[1]);if(ac>2)B=atoi(av[2]);vector<pair<int,int>>p{{0,0}};gen(0,0,0,0,p);cerr<<"states="<<codes.size()<<"\n";idx.reserve(codes.size()*13/10);idx.max_load_factor(.8);for(uint32_t i=0;i<codes.size();i++)idx[codes[i]]=i;uint64_t mask=(1ull<<(2*K))-1;vector<array<int32_t,4>>tr(codes.size());vector<uint8_t>deg(codes.size());for(size_t i=0;i<codes.size();i++)for(int d=0;d<4;d++)if(okapp(codes[i],d)){uint32_t nc=((uint64_t(codes[i])<<2)|d)&mask;tr[i][deg[i]++]=idx.at(nc);}vector<U>f(codes.size(),1),nf(codes.size()),C(B+1);C[0]=1;for(int b=1;b<=B;b++){U mx=0;for(size_t i=0;i<codes.size();i++){U z=0;for(int j=0;j<deg[i];j++)z+=f[tr[i][j]];nf[i]=z;mx=max(mx,z);}f.swap(nf);C[b]=mx;if(b%10==0)cerr<<"b="<<b<<"\n";}cpp_int bound=0,cK=codes.size();for(int l=54;l<=782;l+=2){int rem=l-K,q=rem/B,r=rem%B;cpp_int z=cK;for(int j=0;j<q;j++)z*=tobig(C[B]);if(r)z*=tobig(C[r]);bound+=z;}cout<<"K="<<K<<" B="<<B<<" states="<<codes.size()<<" bound_bits="<<(boost::multiprecision::msb(bound)+1)<<"\n";}
